css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .66); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 16%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 22%, var(--accent-2)), color-mix(in srgb, #000 42%, var(--accent-2))); }
.loader::before { content: ''; position: absolute; z-index: 2; bottom: 16%; left: 6%; width: 36%; height: 34%; background: linear-gradient(90deg, color-mix(in srgb, #000 44%, var(--accent-2)) 0 20%, transparent 20%), repeating-linear-gradient(to bottom, var(--accent-2) 0 18%, transparent 18% 34%); }
.loader .cylinder { position: absolute; bottom: 18%; right: 7%; width: 44%; height: 62%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 12%, var(--accent)) 0 60%, transparent 61%), repeating-conic-gradient(from 0deg, color-mix(in srgb, #000 58%, var(--accent)) 0 3.5deg, transparent 3.5deg 22deg); animation: cyl-spin calc(var(--loader-speed) * 2.6) linear infinite; }
.loader .cylinder::after { content: ''; position: absolute; inset: 40%; border-radius: 50%; background: color-mix(in srgb, #000 45%, var(--accent)); }
.loader span { position: absolute; bottom: 48%; left: 20%; width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .085); border-radius: 50%; background: var(--accent-2); animation: note-float calc(var(--loader-speed) * 2.2) ease-out infinite; }
.loader span::after { content: ''; position: absolute; left: 82%; bottom: 40%; width: 22%; height: 190%; border-radius: 1px; background: var(--accent-2); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * 1.1); }
@keyframes cyl-spin { to { transform: rotate(360deg); } }
@keyframes note-float { 0% { opacity: 0; transform: translate(0, 0) rotate(-8deg); } 22% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size) * -.14), calc(var(--loader-size) * -.36)) rotate(14deg); } }
